mapreduce.pseudocode:
def map_fn(doc_id, text):  # Map: 단어마다 (단어, 1)
    for word in text.split():
        yield word, 1

def reduce_fn(word, counts):  # Reduce: 키별 집계
    return word, sum(counts)

def run_job(docs):  # 프레임워크 흐름(단일 노드 모사)
    groups = {}
    for doc_id, text in docs.items():  # 맵 태스크 병렬
        for k, v in map_fn(doc_id, text):
            groups.setdefault(k, []).append(v)  # 셔플
    keys = sorted(groups)  # 키 정렬
    return [reduce_fn(k, groups[k]) for k in keys]

mark-and-sweep.pseudocode:
def mark(roots):  # 루트에서 도달 가능한 객체 표시
    stack = list(roots)
    while stack:
        obj = stack.pop()
        if not obj.marked:
            obj.marked = True
            stack.extend(obj.refs)  # 참조 대상 계속 추적

def sweep(heap):  # 표시 안 된 객체 회수
    for obj in list(heap):
        if obj.marked:
            obj.marked = False  # 다음 GC를 위해 초기화
        else:
            heap.remove(obj)  # 도달 불가 → 메모리 해제

def collect(roots, heap):
    mark(roots)  # Stop-the-World 구간
    sweep(heap)

markov-chain-monte-carlo.pseudocode:
def metropolis_hastings(p, x0, n, step):
    # p: 정규화 상수 몰라도 되는 목표 밀도(비례값)
    x, samples = x0, []
    for _ in range(n):
        y = x + gaussian(0, step)  # 대칭 제안 분포
        alpha = min(1.0, p(y) / p(x))  # 수락 확률
        if random() < alpha:
            x = y  # 수락, 거절이면 현재 값 유지
        samples.append(x)
    return samples[n // 10:]  # 앞 10% 번인 제외

markov-decision-process.pseudocode:
def q_value(s, a, V, P, R, gamma):
    # P[s][a]: {다음 상태: 확률}
    return R[s][a] + gamma * sum(
        p * V[s2] for s2, p in P[s][a].items())

def value_iteration(S, A, P, R, gamma, eps=1e-6):
    V = {s: 0.0 for s in S}
    while True:
        delta = 0.0
        for s in S:  # 벨만 최적 방정식으로 갱신
            best = max(q_value(s, a, V, P, R, gamma)
                       for a in A)
            delta = max(delta, abs(best - V[s]))
            V[s] = best
        if delta < eps:  # 수렴
            break
    pi = {s: max(A, key=lambda a:
                 q_value(s, a, V, P, R, gamma)) for s in S}
    return V, pi  # 최적 가치함수·정책

masked-language-model.pseudocode:
def mask_tokens(tokens, vocab, rate=0.15):
    inputs, labels = list(tokens), [None] * len(tokens)
    for i, tok in enumerate(tokens):
        if random() < rate:  # 예측 대상 선택
            labels[i] = tok
            r = random()
            if r < 0.8:
                inputs[i] = '[MASK]'
            elif r < 0.9:
                inputs[i] = random_choice(vocab)
            # 나머지 10%는 원 토큰 유지
    return inputs, labels  # 손실은 labels 있는 위치만

master-theorem.pseudocode:
def master(a, b, k):  # T(n) = aT(n/b) + Θ(n^k)
    # n^(log_b a)와 n^k 비교 = a와 b^k 비교
    if a > b ** k:
        return 'Θ(n^(log_b a))'  # 경우 1: 리프 지배
    if a == b ** k:
        return 'Θ(n^k · log n)'  # 경우 2: 균등 분포
    return 'Θ(n^k)'  # 경우 3: 루트 지배

# 병합 정렬 master(2, 2, 1) → Θ(n log n)
# 이진 탐색 master(1, 2, 0) → Θ(log n)
# 스트라센 master(7, 2, 2) → Θ(n^(log2 7))

maximum-likelihood-estimation.pseudocode:
def goel_okumoto_mle(times, T):  # m(t) = a(1 - e^-bt)
    # times: 고장 발생 시각들, T: 관측 종료 시각
    n, s = len(times), sum(times)
    def g(b):  # ∂ℓ/∂b = 0 을 만족하는 b 탐색
        e = exp(-b * T)
        return n / b - s - n * T * e / (1 - e)
    lo, hi = 1e-9, 10.0  # 신뢰도 성장 시 해 존재
    for _ in range(100):  # 이분법(수치 해법)
        mid = (lo + hi) / 2
        if g(mid) > 0:
            lo = mid
        else:
            hi = mid
    b = (lo + hi) / 2  # 결함 검출률
    a = n / (1 - exp(-b * T))  # 총 기대 결함 수
    return a, b
